                "code": "class AVLNode:\n    __slots__ = (\"key\", \"left\", \"right\", \"height\")\n\n    def __init__(self, key):\n        self.key, self.left, self.right, self.height = key, None, None, 1\n\n\ndef height(n):\n    return n.height if n else 0\n\n\ndef update(n):\n    n.height = 1 + max(height(n.left), height(n.right))\n\n\ndef balance_factor(n):\n    return height(n.left) - height(n.right)\n\n\ndef rotate_right(y):\n    x = y.left\n    y.left, x.right = x.right, y\n    update(y); update(x)                  # y is now below x: update it first\n    return x\n\n\ndef rotate_left(x):\n    y = x.right\n    x.right, y.left = y.left, x\n    update(x); update(y)\n    return y\n\n\ndef rebalance(n):\n    update(n)\n    bf = balance_factor(n)\n    if bf > 1:                            # left heavy\n        if balance_factor(n.left) < 0:    # LR: straighten it into LL first\n            n.left = rotate_left(n.left)\n        return rotate_right(n)            # LL\n    if bf < -1:                           # right heavy\n        if balance_factor(n.right) > 0:   # RL\n            n.right = rotate_right(n.right)\n        return rotate_left(n)             # RR\n    return n\n\n\nclass AVLTree:\n    def __init__(self):\n        self.root = None\n\n    def insert(self, key):\n        self.root = self._insert(self.root, key)\n\n    def _insert(self, n, key):\n        if n is None:\n            return AVLNode(key)\n        if key < n.key:\n            n.left = self._insert(n.left, key)\n        elif key > n.key:\n            n.right = self._insert(n.right, key)\n        else:\n            return n                      # already present\n        return rebalance(n)\n\n    def delete(self, key):\n        self.root = self._delete(self.root, key)\n\n    def _delete(self, n, key):\n        if n is None:\n            return None\n        if key < n.key:\n            n.left = self._delete(n.left, key)\n        elif key > n.key:\n            n.right = self._delete(n.right, key)\n        else:\n            if n.left is None:\n                return n.right\n            if n.right is None:\n                return n.left\n            succ = n.right                # two children: take the successor\n            while succ.left is not None:\n                succ = succ.left\n            n.key = succ.key\n            n.right = self._delete(n.right, succ.key)\n        return rebalance(n)\n\n    def __contains__(self, key):\n        n = self.root\n        while n is not None and n.key != key:\n            n = n.left if key < n.key else n.right\n        return n is not None\n\n    def inorder(self):\n        out, stack, n = [], [], self.root\n        while stack or n:\n            while n:\n                stack.append(n)\n                n = n.left\n            n = stack.pop()\n            out.append(n.key)\n            n = n.right\n        return out",
